#!/usr/bin/env python3
"""Concatenate section files into one voices file.

usage: python3 tools/assemble.py [--measure 1] [--out score/music-voices.ly]
Reads score/sections/secNN*.ly in name order. Each section file contains the SAME voice variables
(soprano, alto, tenor, bass as \\absolute { ... }) covering exactly that section's bars, plus a
first-line comment '% bars A-B'. Writes the concatenation (section boundaries marked with comments)
and reports each section's length in bars so gaps/overlaps are caught.
"""
import glob, re, sys
from fractions import Fraction as F
sys.path.insert(0, __import__('os').path.dirname(__file__))
from lyparse import parse_voice

VOICES = ['soprano', 'alto', 'tenor', 'bass']
args = sys.argv[1:]
measure = F(args[args.index('--measure') + 1]) if '--measure' in args else F(1)
out = args[args.index('--out') + 1] if '--out' in args else 'score/music-voices.ly'
files = sorted(glob.glob('score/sections/sec[0-9]*.ly'))
bodies = {v: [] for v in VOICES}
bar = 1
ok = True
for f in files:
    src = open(f).read()
    m = re.search(r'%\s*bars\s+(\d+)\s*-\s*(\d+)', src)
    lens = {}
    for v in VOICES:
        mm = re.search(r"(?m)^" + v + r"\s*=\s*\\absolute\s*\{(.*?)^\}", src, re.S)
        if not mm:
            print(f"ERR {f}: missing voice {v}"); ok = False; continue
        notes = parse_voice(src, v, measure)
        lens[v] = sum(n.dur for n in notes) / measure
        bodies[v].append(f"  % ---- {f.split('/')[-1]} (bars {bar}-{bar + int(max(lens.values()) if lens else 0) - 1})\n" + mm.group(1).rstrip() + "\n")
    L = set(lens.values())
    if len(L) != 1:
        print(f"ERR {f}: voices differ in length {lens}"); ok = False
    n = int(max(L)) if L else 0
    if m and (int(m.group(1)) != bar or int(m.group(2)) != bar + n - 1):
        print(f"WARN {f}: header says bars {m.group(1)}-{m.group(2)} but content is bars {bar}-{bar + n - 1}")
    print(f"{f.split('/')[-1]:28s} bars {bar:3d}-{bar + n - 1:3d} ({n})")
    bar += n
with open(out, 'w') as fh:
    fh.write("% GENERATED by tools/assemble.py from score/sections/ -- do not edit by hand\n\n")
    for v in VOICES:
        fh.write(f"{v} = \\absolute {{\n" + "".join(bodies[v]) + "}\n\n")
print(f"total {bar - 1} bars -> {out}" + ("" if ok else "  (WITH ERRORS)"))
sys.exit(0 if ok else 1)
